const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
const bin = typeof pkg.bin === "string" ? pkg.bin : pkg.bin && pkg.bin.agents;
if (!bin) {
  console.error("FAIL: agents " + pkg.version + " publishes no agents bin, so npx agents tui does not exist");
  process.exit(1);
}
const cli = fs.readFileSync(path.join(root, bin), "utf8");
const listed = cli.includes("tui <url>   Chat with an agent's Web Channel from the terminal");
const dispatched = /===\s*`tui`|===\s*"tui"/.test(cli);
const usage = cli.includes("Usage: agents tui <url>");
if (!listed || !dispatched || !usage) {
  console.error("FAIL: the agents bin " + bin + " has no tui command (listed=" + listed + ", dispatched=" + dispatched + ", usage=" + usage + ")");
  process.exit(1);
}
console.log("OK: agents " + pkg.version + " bin " + bin + " lists and dispatches the tui command");

